BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $admin_current_permissions$
DECLARE expected jsonb; original_function pg_catalog.pg_proc%rowtype;
 after_function pg_catalog.pg_proc%rowtype; definition text; actual_hash text;
 config constant jsonb := '[{"signature":"public.canonical_authenticated_tenant_context_v1_scoped(uuid)","before":["b0dea96f47a97fd921850bcb8c39da89","20800ecdbc19c53dd48b5bd8f3376bc1"],"after":"d205c4e8ba1989b27b4df6b1b76af631","patched":"\ndeclare\n  v_user_id uuid := auth.uid();\n  v_user_email text;\n  v_platform boolean := false;\n  v_profile_active boolean := false;\n  v_selected_company_id uuid;\n  v_memberships jsonb := ''[]''::jsonb;\n  v_roles jsonb := ''[]''::jsonb;\n  v_permissions jsonb := ''[]''::jsonb;\n  v_active_permission_keys jsonb := ''[]''::jsonb;\n  v_denied_permissions jsonb := ''[]''::jsonb;\n  v_company jsonb;\n  v_policy jsonb := ''{}''::jsonb;\nbegin\n  if v_user_id is null then\n    return jsonb_build_object(''authorized'',false,''reason_code'',''authentication_required'');\n  end if;\n\n  select exists(\n    select 1 from auth.users u\n    join public.user_profiles profile on profile.id=u.id\n    where u.id=v_user_id and u.deleted_at is null\n      and (u.banned_until is null or u.banned_until <= clock_timestamp())\n      and u.email_confirmed_at is not null\n      and profile.user_status=''active''\n  ) into v_profile_active;\n  if not v_profile_active then\n    return jsonb_build_object(''authorized'',false,''reason_code'',''identity_not_active'');\n  end if;\n\n  v_platform := public.canonical_actor_is_platform_admin(v_user_id);\n  select u.email into v_user_email from auth.users u where u.id=v_user_id;\n\n  if v_platform then\n    select coalesce(jsonb_agg(jsonb_build_object(\n      ''membership_id'',null,\n      ''company_id'',company.id,\n      ''company_name'',company.name,\n      ''company_slug'',company.slug,\n      ''org_number'',company.org_number,\n      ''membership_role'',''platform_admin'',\n      ''role_key'',''platform_admin'',\n      ''status'',company.status\n    ) order by company.name),''[]''::jsonb)\n    into v_memberships\n    from public.companies company\n    where company.status <> ''deleted_test_only'';\n\n    if p_selected_company_id is not null and exists(\n      select 1 from public.companies where id=p_selected_company_id and status <> ''deleted_test_only''\n    ) then\n      v_selected_company_id := p_selected_company_id;\n    end if;\n  else\n    select coalesce(jsonb_agg(jsonb_build_object(\n      ''membership_id'',membership.id,\n      ''company_id'',company.id,\n      ''company_name'',company.name,\n      ''company_slug'',company.slug,\n      ''org_number'',company.org_number,\n      ''membership_role'',membership.membership_role,\n      ''role_key'',role.key,\n      ''status'',company.status\n    ) order by (membership.membership_role=''owner'') desc, company.name),''[]''::jsonb)\n    into v_memberships\n    from public.company_memberships membership\n    join public.companies company on company.id=membership.company_id\n    join public.user_roles user_role\n      on user_role.user_id=membership.user_id\n     and user_role.company_id=membership.company_id\n     and coalesce(user_role.status,''active'')=''active''\n     and coalesce(user_role.is_active,true)\n    join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)\n    where membership.user_id=v_user_id\n      and membership.status=''active''\n      and coalesce(membership.is_active,true);\n\n    select company_id into v_selected_company_id\n    from public.company_memberships membership\n    where membership.user_id=v_user_id\n      and membership.status=''active''\n      and coalesce(membership.is_active,true)\n      and (p_selected_company_id is null or membership.company_id=p_selected_company_id)\n      and exists(\n        select 1 from public.user_roles user_role\n        where user_role.user_id=membership.user_id\n          and user_role.company_id=membership.company_id\n          and coalesce(user_role.status,''active'')=''active''\n          and coalesce(user_role.is_active,true)\n      )\n    order by (membership.company_id=p_selected_company_id) desc,\n             (membership.membership_role=''owner'') desc,\n             membership.created_at\n    limit 1;\n  end if;\n\n  select coalesce(jsonb_agg(distinct role.key),''[]''::jsonb)\n  into v_roles\n  from public.user_roles user_role\n  join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)\n  where user_role.user_id=v_user_id\n    and coalesce(user_role.status,''active'')=''active''\n    and coalesce(user_role.is_active,true)\n    and (user_role.company_id is null or user_role.company_id=v_selected_company_id);\n\n  select coalesce(jsonb_agg(distinct permission.key),''[]''::jsonb)\n  into v_permissions\n  from public.user_roles user_role\n  join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)\n  join public.role_permissions role_permission on role_permission.role_id=role.id\n  join public.permissions permission on permission.id=role_permission.permission_id\n  where user_role.user_id=v_user_id\n    and coalesce(user_role.status,''active'')=''active''\n    and coalesce(user_role.is_active,true)\n    and (user_role.company_id is null or user_role.company_id=v_selected_company_id)\n    and coalesce(role_permission.effect,''allow'')=''allow''\n    -- Catalog and current DENY precedence match the canonical actor oracle.\n    -- Keep this list''s original grants and historical/lifecycle semantics;\n    -- the operational actor oracle itself is not a history-read list filter.\n    and permission.is_active\n    and not exists(\n      select 1 from public.user_permissions d left join public.permissions p on p.id=d.permission_id\n      where d.user_id=v_user_id and (d.company_id is null or d.company_id=v_selected_company_id)\n        and d.is_active and d.status=''active'' and d.effect=''deny''\n        and coalesce(nullif(d.permission_key,''''),p.key)=permission.key\n    )\n    and not exists(\n      select 1 from public.user_permission_overrides d\n      where d.user_id=v_user_id and (d.company_id is null or d.company_id=v_selected_company_id)\n        and d.is_active and d.effect=''deny'' and d.permission_key=permission.key\n        and (d.valid_from is null or d.valid_from<=clock_timestamp())\n        and (d.valid_to is null or clock_timestamp()<d.valid_to)\n    );\n\n  -- Platform authority remains implicit; explicit current DENY and catalog\n  -- availability are projected separately for actual API requirement evaluation.\n  select coalesce(jsonb_agg(permission.key order by permission.key),''[]''::jsonb)\n  into v_active_permission_keys from public.permissions permission where permission.is_active;\n  select coalesce(jsonb_agg(denied.permission_key order by denied.permission_key),''[]''::jsonb)\n  into v_denied_permissions from (\n    select coalesce(nullif(d.permission_key,''''),p.key) as permission_key\n    from public.user_permissions d left join public.permissions p on p.id=d.permission_id\n    where d.user_id=v_user_id and (d.company_id is null or d.company_id=v_selected_company_id)\n      and d.is_active and d.status=''active'' and d.effect=''deny''\n    union\n    select d.permission_key from public.user_permission_overrides d\n    where d.user_id=v_user_id and (d.company_id is null or d.company_id=v_selected_company_id)\n      and d.is_active and d.effect=''deny''\n      and (d.valid_from is null or d.valid_from<=clock_timestamp())\n      and (d.valid_to is null or clock_timestamp()<d.valid_to)\n  ) denied where denied.permission_key is not null;\n\n  if v_selected_company_id is not null then\n    select jsonb_build_object(\n      ''id'',company.id,\n      ''name'',company.name,\n      ''slug'',company.slug,\n      ''org_number'',company.org_number,\n      ''status'',company.status,\n      ''lifecycle_status'',company.lifecycle_status,\n      ''lifecycle_state_version'',company.lifecycle_state_version\n    ) into v_company\n    from public.companies company where company.id=v_selected_company_id;\n\n    select coalesce(jsonb_object_agg(operation.operation, to_jsonb(decision)),''{}''::jsonb)\n    into v_policy\n    from unnest(array[\n      ''tenant.provisioning.execute'',''email.send'',''webhook.deliver'',\n      ''customer_automation.execute'',''facility_lookup.execute'',\n      ''contract_channel.sell'',''api_client.execute''\n    ]::text[]) operation(operation)\n    cross join lateral public.canonical_tenant_operation_decision(\n      v_selected_company_id, operation.operation\n    ) decision;\n  end if;\n\n  return jsonb_build_object(\n    ''authorized'',true,\n    ''user_id'',v_user_id,\n    ''user_email'',v_user_email,\n    ''is_platform_admin'',v_platform,\n    ''selected_company_id'',v_selected_company_id,\n    ''memberships'',v_memberships,\n    ''roles'',v_roles,\n    ''permissions'',v_permissions,\n    ''active_permission_keys'',v_active_permission_keys,\n    ''denied_permissions'',v_denied_permissions,\n    ''company'',v_company,\n    ''operation_policy'',v_policy,\n    ''access_invariant_ok'',v_platform or v_selected_company_id is not null\n  );\nend\n","attributes":{"signature":"canonical_authenticated_tenant_context_v1_scoped(uuid)","oid":341351,"owner":"postgres","acl":"{postgres=X/postgres}","proargnames":["p_selected_company_id"],"argtypes":"2950","return_type":"jsonb","pronargdefaults":1,"defaults":"NULL::uuid","prosecdef":true,"provolatile":"s","proconfig":["search_path=public, auth, pg_temp"],"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"lanname":"plpgsql"}},{"signature":"public.gridex_get_user_permissions(uuid)","before":["3816b4a0580cdd25aefa05af8715fdf2","d525bc3d56f0baaaca6a47f5694b1a80"],"after":"abc7cf42141a02abdfab33cbd013fee8","patched":"\n  with role_based as (\n    select distinct coalesce(p.key, p.name) as permission_name\n    from public.user_roles ur\n    join public.roles r on r.id = ur.role_id and coalesce(r.is_active, true)\n    join public.role_permissions rp on rp.role_id = r.id and coalesce(rp.effect, ''allow'') = ''allow''\n    join public.permissions p on p.id = rp.permission_id\n    where ur.user_id = p_user_id\n      and coalesce(ur.is_active, true)\n      and coalesce(ur.status, ''active'') = ''active''\n      and (\n        -- a genuinely global platform role\n        (\n          ur.company_id is null\n          and public.gridex_normalize_platform_role(coalesce(r.key, r.name))\n            in (''super_admin'', ''platform_admin'')\n        )\n        -- or a company role, but only while that membership is actually active\n        or exists (\n          select 1 from public.company_memberships m\n          where m.user_id = p_user_id\n            and m.company_id = ur.company_id\n            and m.status = ''active''\n            and coalesce(m.is_active, true)\n        )\n      )\n      and coalesce(p.key, p.name) is not null\n      and not exists(\n      select 1 from public.user_permissions d left join public.permissions deny_catalog on deny_catalog.id=d.permission_id\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=ur.company_id)\n        and d.is_active and d.status=''active'' and d.effect=''deny''\n        and coalesce(nullif(d.permission_key,''''),deny_catalog.key)=coalesce(p.key,p.name)\n    ) and not exists(\n      select 1 from public.user_permission_overrides d\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=ur.company_id)\n        and d.is_active and d.effect=''deny'' and d.permission_key=coalesce(p.key,p.name)\n        and (d.valid_from is null or d.valid_from<=clock_timestamp())\n        and (d.valid_to is null or clock_timestamp()<d.valid_to)\n    )\n  ),\n  direct_permissions as (\n    select distinct coalesce(p.key, p.name) as permission_name\n    from public.user_permissions up\n    join public.permissions p on p.id = up.permission_id\n    where up.user_id = p_user_id and coalesce(p.key, p.name) is not null\n      and up.is_active and up.status=''active'' and up.effect=''allow''\n      and not exists(\n      select 1 from public.user_permissions d left join public.permissions deny_catalog on deny_catalog.id=d.permission_id\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=up.company_id)\n        and d.is_active and d.status=''active'' and d.effect=''deny''\n        and coalesce(nullif(d.permission_key,''''),deny_catalog.key)=coalesce(p.key,p.name)\n    ) and not exists(\n      select 1 from public.user_permission_overrides d\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=up.company_id)\n        and d.is_active and d.effect=''deny'' and d.permission_key=coalesce(p.key,p.name)\n        and (d.valid_from is null or d.valid_from<=clock_timestamp())\n        and (d.valid_to is null or clock_timestamp()<d.valid_to)\n    )\n  ),\n  explicit_platform_admin_fallback as (\n    select ''admin.access''::text as permission_name\n    where exists (\n      select 1 from public.admin_users au\n      where au.user_id = p_user_id\n        and coalesce(au.is_active, true)\n        and public.gridex_normalize_platform_role(au.role) in (''super_admin'', ''platform_admin'')\n    )\n  )\n  select coalesce(array_agg(distinct permission_name order by permission_name), ''{}''::text[])\n  from (\n    select permission_name from role_based\n    union select permission_name from direct_permissions\n    union select permission_name from explicit_platform_admin_fallback\n  ) q\n  where permission_name is not null\n    and exists(\n      select 1 from auth.users u join public.user_profiles profile on profile.id=u.id\n      where u.id=p_user_id and u.deleted_at is null\n        and (u.banned_until is null or u.banned_until<=clock_timestamp())\n        and u.email_confirmed_at is not null and profile.user_status=''active''\n    )\n    and exists(select 1 from public.permissions catalog where catalog.key=permission_name and catalog.is_active)\n    and not exists(\n      select 1 from public.user_permissions d left join public.permissions deny_catalog on deny_catalog.id=d.permission_id\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=null::uuid)\n        and d.is_active and d.status=''active'' and d.effect=''deny''\n        and coalesce(nullif(d.permission_key,''''),deny_catalog.key)=permission_name\n    ) and not exists(\n      select 1 from public.user_permission_overrides d\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=null::uuid)\n        and d.is_active and d.effect=''deny'' and d.permission_key=permission_name\n        and (d.valid_from is null or d.valid_from<=clock_timestamp())\n        and (d.valid_to is null or clock_timestamp()<d.valid_to)\n    );\n","attributes":{"signature":"gridex_get_user_permissions(uuid)","oid":19281,"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proargnames":["p_user_id"],"argtypes":"2950","return_type":"text[]","pronargdefaults":0,"defaults":null,"prosecdef":true,"provolatile":"s","proconfig":["search_path=public, auth, pg_temp"],"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"lanname":"sql"}},{"signature":"public.gridex_get_user_permissions_in_company(uuid,uuid)","before":["cbd5976b0516a7aef697f297d0bd0e49"],"after":"cd48d5a1fc77db9fc4cfb62b58e5ad5c","patched":"\n  with role_based as (\n    select distinct coalesce(p.key, p.name) as permission_name\n    from public.user_roles ur\n    join public.roles r on r.id = ur.role_id and coalesce(r.is_active, true)\n    join public.role_permissions rp on rp.role_id = r.id and coalesce(rp.effect, ''allow'') = ''allow''\n    join public.permissions p on p.id = rp.permission_id\n    where ur.user_id = p_user_id\n      and coalesce(ur.is_active, true)\n      and coalesce(ur.status, ''active'') = ''active''\n      and (\n        -- platform roles apply everywhere; company roles only in their own company,\n        -- and only while the membership backing them is active\n        (\n          ur.company_id is null\n          and public.gridex_normalize_platform_role(coalesce(r.key, r.name))\n            in (''super_admin'', ''platform_admin'')\n        )\n        or (\n          p_company_id is not null\n          and ur.company_id = p_company_id\n          and exists (\n            select 1 from public.company_memberships m\n            where m.user_id = p_user_id\n              and m.company_id = ur.company_id\n              and m.status = ''active''\n              and coalesce(m.is_active, true)\n          )\n        )\n      )\n      and coalesce(p.key, p.name) is not null\n  ),\n  direct_permissions as (\n    select distinct coalesce(p.key, p.name) as permission_name\n    from public.user_permissions up\n    join public.permissions p on p.id = up.permission_id\n    where up.user_id = p_user_id and coalesce(p.key, p.name) is not null\n      and coalesce(up.status, ''active'') = ''active''\n      and coalesce(up.is_active, true)\n      and coalesce(up.effect, ''allow'') = ''allow''\n      and (\n        -- Preserve legacy global direct grants. Company-bound grants need the\n        -- same selected-company membership as the unchanged role branch.\n        up.company_id is null\n        or (\n          p_company_id is not null\n          and up.company_id = p_company_id\n          and exists (\n            select 1 from public.company_memberships m\n            where m.user_id = p_user_id\n              and m.company_id = up.company_id\n              and m.status = ''active''\n              and coalesce(m.is_active, true)\n          )\n        )\n      )\n  ),\n  explicit_platform_admin_fallback as (\n    select ''admin.access''::text as permission_name\n    where exists (\n      select 1 from public.admin_users au\n      where au.user_id = p_user_id\n        and coalesce(au.is_active, true)\n        and public.gridex_normalize_platform_role(au.role) in (''super_admin'', ''platform_admin'')\n    )\n  )\n  select coalesce(array_agg(distinct permission_name order by permission_name), ''{}''::text[])\n  from (\n    select permission_name from role_based\n    union select permission_name from direct_permissions\n    union select permission_name from explicit_platform_admin_fallback\n  ) q\n  where permission_name is not null\n    and exists(\n      select 1 from auth.users u join public.user_profiles profile on profile.id=u.id\n      where u.id=p_user_id and u.deleted_at is null\n        and (u.banned_until is null or u.banned_until<=clock_timestamp())\n        and u.email_confirmed_at is not null and profile.user_status=''active''\n    )\n    and exists(select 1 from public.permissions catalog where catalog.key=permission_name and catalog.is_active)\n    and not exists(\n      select 1 from public.user_permissions d left join public.permissions deny_catalog on deny_catalog.id=d.permission_id\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=p_company_id)\n        and d.is_active and d.status=''active'' and d.effect=''deny''\n        and coalesce(nullif(d.permission_key,''''),deny_catalog.key)=permission_name\n    ) and not exists(\n      select 1 from public.user_permission_overrides d\n      where d.user_id=p_user_id and (d.company_id is null or d.company_id=p_company_id)\n        and d.is_active and d.effect=''deny'' and d.permission_key=permission_name\n        and (d.valid_from is null or d.valid_from<=clock_timestamp())\n        and (d.valid_to is null or clock_timestamp()<d.valid_to)\n    );\n","attributes":{"signature":"gridex_get_user_permissions_in_company(uuid,uuid)","oid":356774,"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proargnames":["p_user_id","p_company_id"],"argtypes":"2950 2950","return_type":"text[]","pronargdefaults":0,"defaults":null,"prosecdef":true,"provolatile":"s","proconfig":["search_path=public, auth, pg_temp"],"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"lanname":"sql"}},{"signature":"public.gridex_has_permission(uuid,text)","before":["95f70460c927b0b7133872ee8418bafe"],"after":"62ab7072f95952b588f784c9e5956870","patched":"\n  select p_user_id is not null\n    and p_permission is not null\n    and exists(\n      select 1 from auth.users u join public.user_profiles profile on profile.id=u.id\n      where u.id=p_user_id and u.deleted_at is null\n        and (u.banned_until is null or u.banned_until<=clock_timestamp())\n        and u.email_confirmed_at is not null and profile.user_status=''active''\n    )\n    and p_permission = any(public.gridex_get_user_permissions(p_user_id));\n","attributes":{"signature":"gridex_has_permission(uuid,text)","oid":19282,"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","proargnames":["p_user_id","p_permission"],"argtypes":"2950 25","return_type":"boolean","pronargdefaults":0,"defaults":null,"prosecdef":true,"provolatile":"s","proconfig":["search_path=public, auth, pg_temp"],"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"lanname":"sql"}},{"signature":"public.gridex_has_permission_in_company(uuid,text)","before":["d1dfece66dc545141e0a1677e60263c6"],"after":"c734e54d5f3a33eaa3b2f5a0bbd4d9ba","patched":"\n  select p_company_id is not null\n    and p_permission is not null\n    and (select auth.uid()) is not null\n    and exists(\n      select 1 from auth.users u join public.user_profiles profile on profile.id=u.id\n      where u.id=(select auth.uid()) and u.deleted_at is null\n        and (u.banned_until is null or u.banned_until<=clock_timestamp())\n        and u.email_confirmed_at is not null and profile.user_status=''active''\n    )\n    and p_permission = any(\n      public.gridex_get_user_permissions_in_company((select auth.uid()), p_company_id)\n    );\n","attributes":{"signature":"gridex_has_permission_in_company(uuid,text)","oid":356773,"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","proargnames":["p_company_id","p_permission"],"argtypes":"2950 25","return_type":"boolean","pronargdefaults":0,"defaults":null,"prosecdef":true,"provolatile":"s","proconfig":["search_path=public, auth, pg_temp"],"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"lanname":"sql"}}]'::jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM (VALUES
  ('public.permissions','id'),('public.permissions','key'),('public.permissions','is_active'),
  ('public.user_permissions','user_id'),('public.user_permissions','company_id'),('public.user_permissions','permission_id'),
  ('public.user_permissions','permission_key'),('public.user_permissions','is_active'),('public.user_permissions','status'),('public.user_permissions','effect'),
  ('public.user_permission_overrides','user_id'),('public.user_permission_overrides','company_id'),
  ('public.user_permission_overrides','permission_key'),('public.user_permission_overrides','is_active'),('public.user_permission_overrides','effect'),
  ('public.user_permission_overrides','valid_from'),('public.user_permission_overrides','valid_to'),
  ('auth.users','id'),('auth.users','deleted_at'),('auth.users','banned_until'),('auth.users','email_confirmed_at'),
  ('public.user_profiles','id'),('public.user_profiles','user_status')
 ) required(relation_name,column_name) WHERE NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute a
  WHERE a.attrelid=to_regclass(required.relation_name) AND a.attname=required.column_name AND a.attnum>0 AND NOT a.attisdropped)) THEN
  RAISE EXCEPTION 'admin_current_permission_dependencies_unavailable';
 END IF;
 FOR expected IN SELECT e FROM jsonb_array_elements(config) e LOOP
  SELECT * INTO STRICT original_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(expected->>'signature');
  IF original_function.prokind<>'f' OR NOT original_function.prosecdef
   OR pg_get_userbyid(original_function.proowner)<>expected->'attributes'->>'owner'
   OR original_function.proacl::text IS DISTINCT FROM expected->'attributes'->>'acl'
   OR original_function.proargtypes::text<>expected->'attributes'->>'argtypes'
   OR original_function.prorettype::regtype::text<>expected->'attributes'->>'return_type'
   OR original_function.proargnames IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(expected->'attributes'->'proargnames'))
   OR original_function.proconfig IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(expected->'attributes'->'proconfig'))
   OR original_function.pronargdefaults<>(expected->'attributes'->>'pronargdefaults')::int
   OR pg_get_expr(original_function.proargdefaults,0) IS DISTINCT FROM expected->'attributes'->>'defaults'
   OR original_function.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname=expected->'attributes'->>'lanname')
   OR original_function.proisstrict OR original_function.proleakproof OR original_function.proparallel<>'u'
   OR original_function.procost<>100 OR original_function.prorows<>0 OR original_function.provolatile NOT IN ('s','v') THEN
   RAISE EXCEPTION 'admin_current_permission_attributes_changed_requires_review: %',expected->>'signature';
  END IF;
  actual_hash:=md5(original_function.prosrc);
  IF actual_hash<>expected->>'after' AND NOT (expected->'before' ? actual_hash) THEN
   RAISE EXCEPTION 'admin_current_permission_body_changed_requires_review: %',expected->>'signature';
  END IF;
  IF actual_hash=expected->>'after' AND original_function.provolatile='v' THEN CONTINUE;END IF;
  definition:=pg_get_functiondef(original_function.oid);
  definition:=replace(definition,original_function.prosrc,expected->>'patched');
  -- pg_get_functiondef prints SQL/PLpgSQL STABLE explicitly; default is VOLATILE.
  definition:=replace(definition,' STABLE SECURITY DEFINER',' VOLATILE SECURITY DEFINER');
  IF original_function.provolatile='i' THEN RAISE EXCEPTION 'admin_current_permission_unqualified_immutable_function';END IF;
  EXECUTE definition;
  SELECT * INTO STRICT after_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(expected->>'signature');
  IF (to_jsonb(after_function)-'prosrc'-'provolatile')
       IS DISTINCT FROM (to_jsonb(original_function)-'prosrc'-'provolatile')
   OR after_function.oid<>original_function.oid OR after_function.proowner<>original_function.proowner
   OR after_function.proacl IS DISTINCT FROM original_function.proacl
   OR after_function.proargtypes IS DISTINCT FROM original_function.proargtypes
   OR after_function.proargnames IS DISTINCT FROM original_function.proargnames
   OR after_function.prorettype<>original_function.prorettype
   OR after_function.prosecdef<>original_function.prosecdef
   OR after_function.proconfig IS DISTINCT FROM original_function.proconfig
   OR after_function.proargdefaults IS DISTINCT FROM original_function.proargdefaults
   OR after_function.proisstrict<>original_function.proisstrict OR after_function.proleakproof<>original_function.proleakproof
   OR after_function.proparallel<>original_function.proparallel OR after_function.procost<>original_function.procost
   OR after_function.prorows<>original_function.prorows OR after_function.provolatile<>'v'
   OR md5(after_function.prosrc)<>expected->>'after' THEN
   RAISE EXCEPTION 'admin_current_permission_identity_preservation_required: %',expected->>'signature';
  END IF;
 END LOOP;
END
$admin_current_permissions$;
NOTIFY pgrst,'reload schema';
COMMIT;
